CREATE TABLE user_consumable(id INTEGER PRIMARY KEY,user_id TEXT NOT NULL REFERENCES user(id),consumable_id INTEGER NOT NULL,cooldown_until INTEGER NOT NULL DEFAULT 0,quantity INTEGER NOT NULL DEFAULT 0,created_at DATETIME DEFAULT CURRENT_TIMESTAMP,updated_at DATETIME DEFAULT CURRENT_TIMESTAMP,UNIQUE(user_id,consumable_id));
CREATE TABLE user_buff(id INTEGER PRIMARY KEY,user_id TEXT NOT NULL REFERENCES user(id),buff_id TEXT NOT NULL,buff_type TEXT NOT NULL DEFAULT 'consumable',value REAL DEFAULT 1,duration INTEGER DEFAULT 0,expires_at DATETIME,created_at DATETIME DEFAULT CURRENT_TIMESTAMP,active_until INTEGER NOT NULL DEFAULT 0,cooldown_until INTEGER NOT NULL DEFAULT 0,giver_user_id TEXT NOT NULL DEFAULT '',UNIQUE(user_id,buff_id));
CREATE TABLE user_wing_buff(id INTEGER PRIMARY KEY,user_id TEXT NOT NULL REFERENCES user(id),name TEXT NOT NULL,collected INTEGER NOT NULL DEFAULT 0,deposited INTEGER NOT NULL DEFAULT 0,last_conversion INTEGER NOT NULL DEFAULT 0,deposit_id INTEGER NOT NULL DEFAULT 0,created_at INTEGER NOT NULL DEFAULT 0,updated_at INTEGER NOT NULL DEFAULT 0,UNIQUE(user_id,name));
CREATE TABLE status_unlock(id INTEGER PRIMARY KEY,user_id TEXT NOT NULL REFERENCES user(id),name TEXT NOT NULL,unlock_type TEXT NOT NULL DEFAULT 'level',ack INTEGER NOT NULL DEFAULT 0,unlocked_at INTEGER NOT NULL DEFAULT 0,created_at DATETIME DEFAULT CURRENT_TIMESTAMP,UNIQUE(user_id,name));
CREATE TABLE status_unlock_deleted(id INTEGER PRIMARY KEY,user_id TEXT NOT NULL REFERENCES user(id),name TEXT NOT NULL,deleted_at INTEGER NOT NULL DEFAULT 0,UNIQUE(user_id,name));
CREATE TABLE item_dye(user_id TEXT NOT NULL REFERENCES user(id),unlock_name TEXT NOT NULL,upgrade_dye TEXT NOT NULL,created_at INTEGER NOT NULL DEFAULT 0,updated_at INTEGER NOT NULL DEFAULT 0,PRIMARY KEY(user_id,unlock_name,upgrade_dye));
